node -e "import('ajv').then(({default: Ajv}) => {
  const ajv = new Ajv({format: false, allErrors: true});
  const v = ajv.compile({
    type: 'object',
    properties: {
      location: {type: 'string'},
      units: {type: 'string', enum: ['celsius', 'fahrenheit']},
      nested: {
        type: 'object',
        properties: {code: {type: 'number'}},
        required: ['code']
      }
    },
    required: ['location']
  });
  v({});
  console.log('missing required:', v.errors);
  v({location: 123, units: 'kelvin', nested: {code: 'abc'}});
  console.log('wrong type & enum & nested:', v.errors);
  v({location: 'Paris', nested: {}});
  console.log('missing nested required:', v.errors);
})"
